namespace tinf {
struct Tree { unsigned short table[16]; unsigned short trans[288]; };
static const unsigned char clcidx[] = {16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};
static unsigned char lbits[30], dbits[30];
static unsigned short lbase[30], dbase[30];
static Tree slt, sdt;
static bool inited = false;
struct Src { const unsigned char *s; int p; int len; };
static unsigned int getbit(Src &d) {
    unsigned int v = (d.s[d.p >> 3] >> (d.p & 7)) & 1; d.p++; return v;
}
static unsigned int getbits(Src &d, int n) {
    unsigned int v = 0; for (int i = 0; i < n; i++) v |= getbit(d) << i; return v;
}
static void build(Tree &t, const unsigned char *lens, int n) {
    unsigned short offs[16]; int i;
    for (i = 0; i < 16; i++) t.table[i] = 0;
    for (i = 0; i < n; i++) t.table[lens[i]]++;
    t.table[0] = 0; offs[0] = 0;
    unsigned int sum = 0;
    for (i = 1; i < 16; i++) { offs[i] = sum; sum += t.table[i]; }
    for (i = 0; i < n; i++) if (lens[i]) t.trans[offs[lens[i]]++] = i;
}
static int decode(Src &d, Tree &t) {
    int sum = 0, cur = 0, len = 0;
    do {
        cur = 2 * cur + getbit(d); len++;
        sum += t.table[len]; cur -= t.table[len];
    } while (cur >= 0);
    return t.trans[sum + cur];
}
static void init() {
    if (inited) return; inited = true;
    int i; unsigned char lens[288];
    for (i = 0; i < 144; i++) lens[i] = 8;
    for (; i < 256; i++) lens[i] = 9;
    for (; i < 280; i++) lens[i] = 7;
    for (; i < 288; i++) lens[i] = 8;
    build(slt, lens, 288);
    for (i = 0; i < 30; i++) lens[i] = 5;
    build(sdt, lens, 30);
    for (i = 0; i < 30; i++) lbits[i] = dbits[i] = 0;
    for (i = 0; i < 30; i++) { if (i >= 8 && i < 28) lbits[i] = (i - 4) / 4; }
    lbase[0]=3; for (i=1;i<30;i++) lbase[i]=lbase[i-1]+(1<<lbits[i-1]);
    for (i = 2; i < 30; i++) dbits[i] = (i - 2) / 2;
    dbase[0]=1; for (i=1;i<30;i++) dbase[i]=dbase[i-1]+(1<<dbits[i-1]);
}
static void block(Src &d, Tree &lt, Tree &dt, unsigned char *out, int &op) {
    for (;;) {
        int sym = decode(d, lt);
        if (sym == 256) return;
        if (sym < 256) { out[op++] = sym; }
        else {
            sym -= 257;
            int length = lbase[sym] + getbits(d, lbits[sym]);
            int dist_sym = decode(d, dt);
            int dist = dbase[dist_sym] + getbits(d, dbits[dist_sym]);
            for (int i = 0; i < length; i++) { out[op] = out[op - dist]; op++; }
        }
    }
}
int inflate(const unsigned char *src, int srclen, unsigned char *dst, int dstcap) {
    init();
    Src d; d.s = src; d.p = 0; d.len = srclen;
    int op = 0, bfinal;
    do {
        bfinal = getbit(d);
        int btype = getbits(d, 2);
        if (btype == 0) {
            d.p = (d.p + 7) & ~7;
            int len = d.s[d.p/8] | (d.s[d.p/8+1]<<8); d.p += 32;
            for (int i = 0; i < len; i++) { dst[op++] = d.s[d.p/8]; d.p += 8; }
        } else if (btype == 1) {
            block(d, slt, sdt, dst, op);
        } else {
            int hlit = getbits(d, 5) + 257;
            int hdist = getbits(d, 5) + 1;
            int hclen = getbits(d, 4) + 4;
            unsigned char clens[19] = {};
            for (int i = 0; i < hclen; i++) clens[clcidx[i]] = getbits(d, 3);
            Tree clt; build(clt, clens, 19);
            unsigned char lens[316] = {};
            int n = 0;
            while (n < hlit + hdist) {
                int s = decode(d, clt);
                if (s < 16) { lens[n++] = s; }
                else if (s == 16) { int c = getbits(d, 2) + 3; for (int i = 0; i < c; i++) lens[n] = lens[n-1], n++; }
                else if (s == 17) { int c = getbits(d, 3) + 3; for (int i = 0; i < c; i++) lens[n++] = 0; }
                else { int c = getbits(d, 7) + 11; for (int i = 0; i < c; i++) lens[n++] = 0; }
            }
            Tree dlt, ddt;
            build(dlt, lens, hlit);
            build(ddt, lens + hlit, hdist);
            block(d, dlt, ddt, dst, op);
        }
    } while (!bfinal);
    return op;
}
} // namespace tinf

static const char B91[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~\"";
static uint8_t bt[128];
void bi(){for(int i=0;i<91;i++)bt[(uint8_t)B91[i]]=i;}
int bd(const char*s,int len,uint8_t*o){
bi();uint32_t b=0;int n=0,v=-1,p=0;
for(int i=0;i<len;i++){
int d=bt[(uint8_t)s[i]];
if(v==-1){v=d;}else{
v+=d*91;b|=v<<n;
n+=((v&8191)>88)?13:14;
while(n>=8){o[p++]=b&0xFF;b>>=8;n-=8;}
v=-1;}}
if(v!=-1){o[p++]=(b|v<<n)&0xFF;}
return p;}

union F16{uint16_t u;};
float f16(uint16_t h){
uint32_t s=(h>>15)&1,e=(h>>10)&0x1F,m=h&0x3FF;
if(e==0){if(m==0)return s?-0.0f:0.0f;
float f=m/1024.0f;f*=1.0f/(1<<14);return s?-f:f;}
if(e==31)return s?-1e30f:1e30f;
float f=(1.0f+m/1024.0f);
for(int i=0;i<(int)e-15;i++)f*=2.0f;
for(int i=0;i<15-(int)e;i++)f*=0.5f;
return s?-f:f;}
constexpr int W=192,OBS=128,NACT=81,APOD=9;
float w0[OBS*W],b0[W],w1[W*W],b1[W],w2[W*NACT],b2[NACT];
void lw(const uint8_t*d){
const uint8_t*sp=d+77457;
auto rs=[&](int i){return f16((uint16_t)(sp[i*2]|(sp[i*2+1]<<8)));};int off=0;
for(int c=0;c<192;c++){float s=rs(0+c);for(int r=0;r<OBS;r++)w0[r*W+c]=((float)d[off++]-127.0f)*s;}
for(int c=0;c<192;c++){float s=rs(192+c);for(int r=0;r<W;r++)w1[r*W+c]=((float)d[off++]-127.0f)*s;}
for(int c=0;c<81;c++){float s=rs(384+c);for(int r=0;r<W;r++)w2[r*NACT+c]=((float)d[off++]-127.0f)*s;}
{float s=rs(465);for(int i=0;i<W;i++)b0[i]=((float)d[off++]-127.0f)*s;}
{float s=rs(466);for(int i=0;i<W;i++)b1[i]=((float)d[off++]-127.0f)*s;}
{float s=rs(467);for(int i=0;i<NACT;i++)b2[i]=((float)d[off++]-127.0f)*s;}
}
void fwd(const float*obs,float*logits){
float h1[W],h2[W];
for(int j=0;j<W;j++){float s=b0[j];for(int i=0;i<OBS;i++)s+=obs[i]*w0[i*W+j];h1[j]=s>0?s:0;}
for(int j=0;j<W;j++){float s=b1[j];for(int i=0;i<W;i++)s+=h1[i]*w1[i*W+j];h2[j]=s>0?s:0;}
for(int j=0;j<NACT;j++){float s=b2[j];for(int i=0;i<W;i++)s+=h2[i]*w2[i*NACT+j];logits[j]=s;}
}
constexpr double PI=3.14159265358979323846,D2R=PI/180.0;
constexpr double MAX_ROT=18.0*D2R;
constexpr double MW=16000.0,MH=9000.0,MV=800.0,MD=18358.0,SM=4.0;
constexpr double RT[9]={-MAX_ROT,0.0,MAX_ROT,-MAX_ROT,0.0,MAX_ROT,-MAX_ROT,0.0,MAX_ROT};
constexpr int TT[9]={0,0,0,200,200,200,0,0,0};
constexpr bool SH[9]={false,false,false,false,false,false,true,true,true};
struct Pod{double x,y,vx,vy,a,pa;int nc,sh;};Pod P[4];
double cx[30],cy[30],gx[60],gy[60];
int nc,la,ng,npl;
int to[2],lc[4],gc[4],ms[2],tn;
void it(){for(int i=0;i<4;i++){lc[i]=-1;gc[i]=1;}tn=0;ms[0]=ms[1]=0;to[0]=to[1]=100;}
void ut(int i,int l){if(lc[i]>=0&&l!=lc[i]){gc[i]++;if(i<2)to[0]=100;else to[1]=100;}lc[i]=l;}
double sc[4];
void cs(){for(int i=0;i<4;i++){int ci=min(gc[i],ng-1);
double dx=P[i].x-gx[ci],dy=P[i].y-gy[ci];
int pi=(i<2)?0:1;
if(to[pi]<=0)sc[i]=-1e9;else sc[i]=gc[i]*50000.0-sqrt(dx*dx+dy*dy);}}
// Observation: 128 dims matching training/physics.py v3
void bo(float*o,int pod){  // pod=0 or 1 (our pods)
int od[4];
if(pod==0){od[0]=0;od[1]=1;od[2]=2;od[3]=3;}
else{od[0]=1;od[1]=0;od[2]=2;od[3]=3;}
double px[4],py[4],vx[4],vy[4],ag[4],pag[4];
int np[4],sh[4];
for(int i=0;i<4;i++){int j=od[i];
px[i]=P[j].x;py[i]=P[j].y;vx[i]=P[j].vx;vy[i]=P[j].vy;
ag[i]=P[j].a;np[i]=gc[j];sh[i]=P[j].sh;pag[i]=P[j].pa;}
double mc=(double)max(ng,1);int pl=min(ng+2,59);int x=0;
// A: core state 32
for(int i=0;i<4;i++)o[x++]=px[i]/MW;
for(int i=0;i<4;i++)o[x++]=py[i]/MH;
for(int i=0;i<4;i++)o[x++]=vx[i]/MV;
for(int i=0;i<4;i++)o[x++]=vy[i]/MV;
for(int i=0;i<4;i++)o[x++]=cos(ag[i]);
for(int i=0;i<4;i++)o[x++]=sin(ag[i]);
for(int i=0;i<4;i++)o[x++]=(float)np[i]/(float)mc;
for(int i=0;i<4;i++)o[x++]=(float)sh[i]/SM;
// B: polar CP 24
for(int p=0;p<4;p++)for(int c=0;c<2;c++){
int g=min(np[p]+c,pl);
double dx=gx[g]-px[p],dy=gy[g]-py[p];
double d=sqrt(dx*dx+dy*dy+1e-8)/MD;
double brg=atan2(dy,dx)-ag[p];
o[x++]=d;o[x++]=cos(brg);o[x++]=sin(brg);}
// C: TTI 6
int pa[]={0,0,0,1,1,2},pb[]={1,2,3,2,3,3};
for(int k=0;k<6;k++){
int i=pa[k],j=pb[k];
double rpx=px[j]-px[i],rpy=py[j]-py[i];
double rvx=vx[j]-vx[i],rvy=vy[j]-vy[i];
double p2=rpx*rpx+rpy*rpy,v2=rvx*rvx+rvy*rvy;
double dot=rpx*rvx+rpy*rvy;
double c2=p2-640000.0;
double disc=dot*dot-v2*c2;
double disc_s=max(disc,0.0);
double sq=sqrt(disc_s);
double den=-dot+sq;
double den_s=(den<=1e-6)?1.0:den;
double tc=c2/den_s;
bool nh=(dot>=0.0)||(disc<0.0)||(v2<1e-6);
bool ol=c2<=0.0;
double tti=ol?0.0:(nh?10.0:min(tc,10.0));
o[x++]=tti/10.0;}
// D: pred dist 12
double m3=2.5725,m6=4.15234;
for(int s=0;s<2;s++){double mt=(s==0)?m3:m6;
double ppx[4],ppy[4];
for(int i=0;i<4;i++){ppx[i]=px[i]+vx[i]*mt;ppy[i]=py[i]+vy[i]*mt;}
for(int k=0;k<6;k++){
double dx=ppx[pa[k]]-ppx[pb[k]],dy=ppy[pa[k]]-ppy[pb[k]];
o[x++]=sqrt(dx*dx+dy*dy+1e-8)/MD;}}
// E: ang vel 4
for(int i=0;i<4;i++){
double da=ag[i]-pag[i];
double dw=atan2(sin(da),cos(da));
double mt=18.0*PI/180.0;
double v=dw/mt;if(v<-1.0)v=-1.0;if(v>1.0)v=1.0;
o[x++]=v;}
// F: exit dir 4
for(int p=0;p<2;p++){
int g0=min(np[p],pl),g1=min(np[p]+1,pl);
double dx=gx[g1]-gx[g0],dy=gy[g1]-gy[g0];
double r=atan2(dy,dx)-ag[p];
o[x++]=cos(r);o[x++]=sin(r);}
// G: game state 3
int m1=max(np[0],np[1]),m2=max(np[2],np[3]);
int pi=(pod==0)?0:1;
o[x++]=to[pi]/100.0f;
o[x++]=to[1-pi]/100.0f;
o[x++]=(float)(m1-m2)/(float)mc;
// H: closing 6
for(int k=0;k<6;k++){
double dx=px[pb[k]]-px[pa[k]],dy=py[pb[k]]-py[pa[k]];
double d=sqrt(dx*dx+dy*dy+1e-8);
o[x++]=-((vx[pb[k]]-vx[pa[k]])*dx+(vy[pb[k]]-vy[pa[k]])*dy)/(d*MV);}
// I: turn sev 8
for(int c=0;c<4;c++){
int c0=min(np[0]+c,pl),c1=min(np[0]+c+1,pl),c2=min(np[0]+c+2,pl);
double d1x=gx[c1]-gx[c0],d1y=gy[c1]-gy[c0];
double d2x=gx[c2]-gx[c1],d2y=gy[c2]-gy[c1];
double ta=atan2(d2y,d2x)-atan2(d1y,d1x);
o[x++]=cos(ta);o[x++]=sin(ta);}
// J: opp face 2
for(int i=2;i<=3;i++){
double dx=px[0]-px[i],dy=py[0]-py[i];
double d=sqrt(dx*dx+dy*dy+1e-8);
o[x++]=cos(ag[i])*(dx/d)+sin(ag[i])*(dy/d);}
// K: shield 2
o[x++]=(sh[0]==4)?1.0f:0.0f;
o[x++]=(sh[1]==4)?1.0f:0.0f;
// scores
cs();double os[4];for(int i=0;i<4;i++)os[i]=sc[od[i]];
int obi=(os[2]>=os[3])?2:3;
// L: ETA 4
for(int p=0;p<4;p++){
int g=min(np[p],ng-1);
double dx=gx[g]-px[p],dy=gy[g]-py[p];
double d=sqrt(dx*dx+dy*dy+1e-8);
double sp=(vx[p]*dx+vy[p]*dy)/d;
double eta=(sp>1.0)?d/sp:50.0;
float ev=eta/50.0;if(ev<0.0f)ev=0.0f;if(ev>1.0f)ev=1.0f;
o[x++]=ev;}
// M: vel align 4
for(int p=0;p<4;p++){
double s=sqrt(vx[p]*vx[p]+vy[p]*vy[p]+1e-8);
o[x++]=(vx[p]*cos(ag[p])+vy[p]*sin(ag[p]))/s;}
// N: opp brg 2
{int ocp=min(np[obi],ng-1);
double odx=gx[ocp]-px[obi],ody=gy[ocp]-py[obi];
double ob=atan2(ody,odx)-ag[obi];
o[x++]=cos(ob);o[x++]=sin(ob);}
// O: vel-cp 4
for(int p=0;p<4;p++){
int g=min(np[p],ng-1);
double dx=gx[g]-px[p],dy=gy[g]-py[p];
double d=sqrt(dx*dx+dy*dy+1e-8);
double sp=sqrt(vx[p]*vx[p]+vy[p]*vy[p]+1e-8);
o[x++]=(vx[p]*dx+vy[p]*dy)/(d*sp);}
// P: path dist 4
{double ld[60];double tt=0;
for(int i=0;i<ng-1;i++){
double dx=gx[i+1]-gx[i],dy=gy[i+1]-gy[i];
ld[i]=sqrt(dx*dx+dy*dy+1e-8);tt+=ld[i];}
tt+=1e-8;
for(int p=0;p<4;p++){
int cc=min(np[p],ng-1);
double di=sqrt((gx[cc]-px[p])*(gx[cc]-px[p])+(gy[cc]-py[p])*(gy[cc]-py[p])+1e-8);
double dr=0;for(int i=cc;i<ng-1;i++)dr+=ld[i];
double v=(di+dr)/tt;if(v<0.0)v=0.0;if(v>1.0)v=1.0;
o[x++]=v;}}
// Q: lateral 4
for(int i=0;i<4;i++)o[x++]=fabs(vx[i]*sin(ag[i])-vy[i]*cos(ag[i]))/MV;
// R: corner 3
for(int p=0;p<3;p++){
int pi2=(p<2)?p:obi;
int cn=min(np[pi2]+1,pl);
double dx=gx[cn]-px[pi2],dy=gy[cn]-py[pi2];
double d=sqrt(dx*dx+dy*dy+1e-8);
o[x++]=(vx[pi2]*dx+vy[pi2]*dy)/(d*MV);}
}
